-- What the Rust migration said of itself:
--
-- Migration: **`artifacts`**. The artifact store's index (T-8 §7, LT-5): one row per stored file. The bytes live on disk under `storage_key`; the row carries what is needed to serve and verify them — name, declared content type, size and the SHA-256 of the bytes. `expires_at` lets a sweep delete a file while the row remains as a tombstone.

CREATE TABLE IF NOT EXISTS "artifacts" ( "created_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL PRIMARY KEY, "pid" uuid NOT NULL UNIQUE, "kind" varchar NOT NULL, "filename" varchar NOT NULL, "content_type" varchar NOT NULL, "size_bytes" bigint NOT NULL, "sha256" varchar NOT NULL, "storage_key" varchar NULL, "created_by" varchar NULL, "expires_at" timestamp with time zone NULL, "deleted_at" timestamp with time zone NULL );

CREATE INDEX artifacts_expiry ON artifacts (expires_at) WHERE expires_at IS NOT NULL AND storage_key IS NOT NULL;
